from pympler.classtracker import ClassTracker
from pympler.process import ProcessMemoryInfo
from pympler.util.stringutils import pp
try:
    from debug_toolbar.panels import Panel
    from django.apps import apps
    from django.template import Context, Template
    from django.template.loader import render_to_string
except ImportError:

    class Panel(object):
        pass


    class Template(object):
        pass


    class Context(object):
        pass


class MemoryPanel(Panel):
    name = b'pympler'
    title = b'Memory'
    template = b'memory_panel.html'
    classes = [
     Context, Template]

    def process_request(self, request):
        self._tracker = ClassTracker()
        for cls in apps.get_models() + self.classes:
            self._tracker.track_class(cls)

        self._tracker.create_snapshot(b'before')
        self.record_stats({b'before': (ProcessMemoryInfo())})
        response = super(MemoryPanel, self).process_request(request)
        self.record_stats({b'after': (ProcessMemoryInfo())})
        self._tracker.create_snapshot(b'after')
        stats = self._tracker.stats
        stats.annotate()
        self.record_stats({b'stats': stats})
        return response

    def enable_instrumentation(self):
        self._tracker = ClassTracker()
        for cls in apps.get_models() + self.classes:
            self._tracker.track_class(cls)

        return

    def disable_instrumentation(self):
        self._tracker.detach_all_classes()
        return

    def nav_subtitle(self):
        context = self.get_stats()
        before = context[b'before']
        after = context[b'after']
        rss = after.rss
        delta = rss - before.rss
        delta = b'(+%s)' % pp(delta) if delta > 0 else b''
        return b'%s %s' % (pp(rss), delta)

    @property
    def content(self):
        context = self.get_stats()
        before = context[b'before']
        after = context[b'after']
        stats = context[b'stats']
        rows = [(b'Resident set size', after.rss),
         (
          b'Virtual size', after.vsz)]
        rows.extend(after - before)
        rows = [(key, pp(value)) for key, value in rows]
        rows.extend(after.os_specific)
        classes = []
        snapshot = stats.snapshots[-1]
        for model in stats.tracked_classes:
            history = [cnt for _, cnt in stats.history[model]]
            size = snapshot.classes.get(model, {}).get(b'sum', 0)
            if history and history[-1] > 0:
                classes.append((model, history, pp(size)))

        context.update({b'rows': rows, b'classes': classes})
        return render_to_string(self.template, context)
